import { createNativeStackNavigator } from '@react-navigation/native-stack';
import React from 'react';
import { useSelector } from 'react-redux';
import AppHeader from '../../components/AppHeader';
import ProductionScreen from '../../screens/superadmin/ProductionScreen';
import ShiftScreen from '../../screens/supervisor/ShiftScreen';
import ProductionMenuScreen from './../../screens/common/ProductionMenuScreen';
import ProductionPlanningScreen from './../../screens/common/ProductionPlanningScreen';
import GenerateCertificateScreen from './../../screens/common/GenerateCertificateScreen';
import HistoryStack from './HistoryStack';
import PlantControlScreen from '../../screens/superadmin/PlantControlScreen';
import PdfViewerScreen from '../../screens/common/PdfViewerScreen';
import ContractorScreen from '../../screens/common/ContractorScreen';
import RateCalculatorScreen from '../../screens/common/RateCalculatorScreen';
import ExpenseReportScreen from '../../screens/common/ExpenseReportScreen';
import ExpenseSettingsScreen from '../../screens/common/ExpenseSettingsScreen';
import MonthlyReportsScreen from '../../screens/common/MonthlyReportsScreen';
import ZincStockScreen from '../../screens/common/ZincStockScreen';
import ZincStockReportScreen from '../../screens/common/ZincStockReportScreen';
import AshDrossReportScreen from '../../screens/common/AshDrossReportScreen';
import ZincStockSettingsScreen from '../../screens/common/ZincStockSettingsScreen';
import ChemicalTrackingScreen from '../../screens/common/ChemicalTrackingScreen';
import LabourWeightsScreen from '../../screens/common/LabourWeightsScreen';
import { COLORS } from '../../assets/Colors';
import { shouldOpenLiveProductionDirectly } from '../../utils/accessNavigation';
const Stack = createNativeStackNavigator();
const renderHeader = props => <AppHeader {...props} />;

export default function ProductionStack() {
  const user = useSelector(state => state.auth.user);
  const directLiveProduction = shouldOpenLiveProductionDirectly(user);

  return (
    <Stack.Navigator
      key={directLiveProduction ? 'direct-live-production' : 'production-menu'}
      initialRouteName={
        directLiveProduction ? 'LiveProduction' : 'ProductionMenu'
      }
      screenOptions={{
        header: renderHeader,
        contentStyle: { backgroundColor: COLORS.bg },
      }}
    >
      <Stack.Screen
        name="LabourWeights"
        component={LabourWeightsScreen}
        options={{ title: 'Labour MS Weights' }}
      />
      <Stack.Screen
        name="ProductionMenu"
        component={ProductionMenuScreen}
        options={{ title: 'Production', headerShown: false }}
      />

      <Stack.Screen
        name="LiveProduction"
        component={ProductionScreen}
        options={{ title: 'Live Production' }}
      />

      <Stack.Screen
        name="ShiftControl"
        component={ShiftScreen}
        options={{ title: 'Automatic Shift' }}
      />

      <Stack.Screen
        name="ProductionHistory"
        component={HistoryStack}
        options={{ title: 'Production History', headerShown: false }}
      />

      <Stack.Screen
        name="ProductionPlanning"
        component={ProductionPlanningScreen}
        options={{ title: 'Production Planning' }}
      />
      <Stack.Screen
        name="Contractors"
        component={ContractorScreen}
        options={{ title: 'Contract Production' }}
      />
      <Stack.Screen
        name="ExpenseReport"
        component={ExpenseReportScreen}
        options={{ title: 'Expense Report' }}
      />
      <Stack.Screen
        name="ExpenseSettings"
        component={ExpenseSettingsScreen}
        options={{ title: 'Expense Settings' }}
      />
      <Stack.Screen
        name="MonthlyReports"
        component={MonthlyReportsScreen}
        options={{ title: 'Monthly Reports' }}
      />
      <Stack.Screen
        name="ZincStock"
        component={ZincStockScreen}
        options={{ title: 'Zinc Stock' }}
      />
      <Stack.Screen
        name="ZincStockReport"
        component={ZincStockReportScreen}
        options={{ title: 'Zinc Stock Report' }}
      />
      <Stack.Screen
        name="ZincStockSettings"
        component={ZincStockSettingsScreen}
        options={{ title: 'Zinc Stock Settings' }}
      />
      <Stack.Screen
        name="AshDrossReport"
        component={AshDrossReportScreen}
        options={{ title: 'Ash & Dross Report' }}
      />
      <Stack.Screen
        name="RateCalculator"
        component={RateCalculatorScreen}
        options={{ title: 'Rate Calculator' }}
      />
      <Stack.Screen
        name="ChemicalTracking"
        component={ChemicalTrackingScreen}
        options={{ title: 'Chemical Tracking' }}
      />

      <Stack.Screen
        name="GenerateCertificate"
        component={GenerateCertificateScreen}
        options={{ title: 'Generate Certificate' }}
      />
      <Stack.Screen
        name="PlantControl"
        component={PlantControlScreen}
        options={{ title: 'Plant Control' }}
      />
      <Stack.Screen
        name="PdfViewer"
        component={PdfViewerScreen}
        options={({ route }) => ({
          title: route.params?.title || 'PDF Preview',
        })}
      />
    </Stack.Navigator>
  );
}
