import React, { useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import { BellRing, Radio, Smartphone, Users } from 'lucide-react-native';
import { TextInput } from 'react-native-paper';
import { useSelector } from 'react-redux';

import {
  sendTestNotificationApi,
  testLatestProductionZincApi,
} from '../../api/notificationApi';
import { COLORS, PAPER_THEME, UI } from '../../assets/Colors';
import { centeredContent, useResponsive } from '../../utils/responsive';

const DEFAULT_TITLE = 'IV Production Notification Test';
const DEFAULT_BODY = 'Backend notification delivery is working for this device.';

export default function NotificationTestScreen() {
  const { contentMaxWidth } = useResponsive();
  const user = useSelector(state => state.auth.user);
  const [title, setTitle] = useState(DEFAULT_TITLE);
  const [body, setBody] = useState(DEFAULT_BODY);
  const [sending, setSending] = useState(false);
  const [delivery, setDelivery] = useState(null);
  const [checkingZinc, setCheckingZinc] = useState(false);
  const [zincCheck, setZincCheck] = useState(null);
  const isSuperadmin =
    String(user?.role || '').toLowerCase().trim() === 'superadmin';

  const sendTest = async () => {
    if (!title.trim() || !body.trim()) {
      Alert.alert('Required', 'Enter a notification title and message.');
      return;
    }

    setSending(true);
    setDelivery(null);
    try {
      const response = await sendTestNotificationApi({
        title: title.trim(),
        body: body.trim(),
      });
      setDelivery({ ...response?.data, message: response?.message });
    } catch (error) {
      Alert.alert(
        'Notification test failed',
        error?.response?.data?.message ||
          'The backend could not run the notification test.',
      );
    } finally {
      setSending(false);
    }
  };

  const testLatestZinc = async () => {
    setCheckingZinc(true);
    setZincCheck(null);
    try {
      const response = await testLatestProductionZincApi();
      setZincCheck(response?.data || null);
    } catch (error) {
      Alert.alert(
        'Zinc trigger test failed',
        error?.response?.data?.message ||
          'The backend could not evaluate the latest production entry.',
      );
    } finally {
      setCheckingZinc(false);
    }
  };

  if (!isSuperadmin) {
    return (
      <View style={styles.centered}>
        <Text style={styles.deniedTitle}>Superadmin access required</Text>
        <Text style={styles.deniedText}>
          Notification delivery tests are restricted to superadmins.
        </Text>
      </View>
    );
  }

  return (
    <ScrollView
      style={styles.screen}
      contentContainerStyle={[
        styles.container,
        centeredContent(contentMaxWidth),
      ]}
      keyboardShouldPersistTaps="handled"
    >
      <View style={styles.introCard}>
        <View style={styles.headerIcon}>
          <BellRing size={22} color={COLORS.accent} />
        </View>
        <View style={styles.flex}>
          <Text style={styles.introText}>
            Sends to active superadmins, admins and plant managers. Supervisors
            are excluded.
          </Text>
        </View>
      </View>

      <View style={styles.card}>
        <Text style={styles.cardTitle}>Test message</Text>
        <TextInput
          label="Notification title"
          mode="outlined"
          value={title}
          onChangeText={setTitle}
          maxLength={120}
          style={styles.input}
          outlineColor={COLORS.inputBorder}
          activeOutlineColor={COLORS.accent}
          theme={PAPER_THEME}
        />
        <TextInput
          label="Notification message"
          mode="outlined"
          value={body}
          onChangeText={setBody}
          maxLength={500}
          multiline
          numberOfLines={4}
          style={styles.input}
          outlineColor={COLORS.inputBorder}
          activeOutlineColor={COLORS.accent}
          theme={PAPER_THEME}
        />
        <TouchableOpacity
          accessibilityRole="button"
          accessibilityLabel="Trigger backend notification test"
          activeOpacity={0.8}
          disabled={sending}
          onPress={sendTest}
          style={[styles.sendButton, sending && styles.buttonDisabled]}
        >
          {sending ? (
            <ActivityIndicator color={COLORS.white} />
          ) : (
            <>
              <Radio size={19} color={COLORS.white} />
              <Text style={styles.sendButtonText}>TRIGGER BACKEND TEST</Text>
            </>
          )}
        </TouchableOpacity>
      </View>

      {delivery && (
        <View style={styles.card}>
          <Text style={styles.cardTitle}>Delivery result</Text>
          <Text style={styles.resultMessage}>{delivery.message}</Text>
          <View style={styles.metricGrid}>
            <Metric
              icon={Users}
              label="Eligible users"
              value={delivery.eligibleUserCount}
            />
            <Metric
              icon={Smartphone}
              label="Registered users"
              value={delivery.registeredUserCount}
            />
            <Metric
              icon={BellRing}
              label="Push delivered"
              value={delivery.successCount}
            />
          </View>
          <Text style={styles.detailText}>
            Device tokens: {delivery.tokenCount || 0} · Push failures:{' '}
            {delivery.failureCount || 0}
          </Text>
          <Text style={styles.detailText}>
            Superadmins: {delivery.roleStats?.superadmin?.registeredUserCount || 0}
            /{delivery.roleStats?.superadmin?.eligibleUserCount || 0} registered
          </Text>
          {delivery.pushErrorCode ? (
            <Text style={styles.errorText}>
              Firebase error: {delivery.pushErrorCode}
            </Text>
          ) : null}
        </View>
      )}

      <View style={styles.card}>
        <Text style={styles.cardTitle}>Production zinc trigger</Text>
        <Text style={styles.resultMessage}>
          Evaluates the latest saved production entry against its linked
          planning challan target. If it qualifies, this replays the real alert
          with a fresh notification key even when it was previously sent.
        </Text>
        <TouchableOpacity
          accessibilityRole="button"
          accessibilityLabel="Test latest production zinc trigger"
          activeOpacity={0.8}
          disabled={checkingZinc}
          onPress={testLatestZinc}
          style={[styles.zincButton, checkingZinc && styles.buttonDisabled]}
        >
          {checkingZinc ? (
            <ActivityIndicator color={COLORS.primary} />
          ) : (
            <Text style={styles.zincButtonText}>CHECK LATEST ZINC ENTRY</Text>
          )}
        </TouchableOpacity>

        {zincCheck ? (
          <View style={styles.zincResult}>
            <Text style={styles.zincResultTitle}>
              {zincCheck.result?.reason || 'UNKNOWN'}
            </Text>
            <Text style={styles.detailText}>
              Challan: {zincCheck.entry?.challan_no || '-'} · SR:{' '}
              {zincCheck.entry?.sr_no || '-'}
            </Text>
            <Text style={styles.detailText}>
              Entry zinc: {zincCheck.result?.zinc ?? zincCheck.entry?.zinc_percentage ?? '-'}% · Target:{' '}
              {zincCheck.result?.target ?? zincCheck.entry?.target_zinc_percentage ?? '-'}%
            </Text>
          </View>
        ) : null}
      </View>

      <View style={styles.helpCard}>
        <Text style={styles.helpTitle}>How to read the result</Text>
        <Text style={styles.helpText}>
          Registered users confirms that the backend has saved FCM tokens. Push
          delivered confirms Firebase accepted the system notification for the
          registered devices.
        </Text>
      </View>
    </ScrollView>
  );
}

function Metric({ icon: Icon, label, value }) {
  return (
    <View style={styles.metric}>
      <Icon size={18} color={COLORS.primary} />
      <Text style={styles.metricValue}>{Number(value) || 0}</Text>
      <Text style={styles.metricLabel}>{label}</Text>
    </View>
  );
}

